#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Solar source comparison: photovoltaic (PV) vs parabolic trough CSP.
================================================================

One file, standard library only (Python 3.8+). It contains

  1. the physics and decision model (sun position, irradiance, PV and trough CSP
     plants with battery / molten-salt storage, cost, land, water, lifecycle CO2,
     weather stress test and the weighted PV-vs-CSP score), and
  2. the interactive 3D scene (Three.js) as an embedded web page, generated by Python.
     The default view is the simple one: a verdict card (best choice, why, score, cost per kWh
     against the grid, payback), a city list, big labelled buttons for weather and camera, a
     play button and time slider. "More" opens the full controls, where one "Explain" button switches on beginner help: "?" pins on
     every part, very short cards (with an advantage/weakness tag for PV or CSP), a guided
     tour, ten predict-then-test experiments, short definitions and hover tips.
     The Impacts and Decision views always carry short labels (ha, ML/yr, g/kWh, halalas/kWh,
     t CO2 saved, and the seven criteria) so every symbol is readable.
  3. cost against the Saudi electricity tariff effective 1 January 2027 (halalas per kWh):
     commercial 25 (35 above 6,000 kWh/month), industrial 23, government 35.
     Source: Saudi Energy schedule as reported by MEED, Saudi Gazette and others, Oct 2026.

The 3D page has an explain mode (the (i) button, top left): numbered markers on every
object and control, and a card saying what it is and why it is there.

Usage
-----
  python solar_3d_model.py                      # writes solar_3d_model.html and opens it
  python solar_3d_model.py html --site riyadh --plant-mw 10 --storage-h 6 --battery-h 6
  python solar_3d_model.py html --embed              # one self-contained file (Three.js inside): works from SharePoint, email, offline
  python solar_3d_model.py serve                     # runs it on http://localhost:8000
  python solar_3d_model.py serve --port 8080 --site riyadh
  python solar_3d_model.py simulate --site jeddah --plant-mw 5 --tariff commercial   # numbers only
  python solar_3d_model.py logo                                     # writes solar_choice_logo.svg
  python solar_3d_model.py sharepoint                               # adds a 'Solar Choice' link to your aPlatforms folder
  python solar_3d_model.py sharepoint --what both                   # link plus the HTML file
  python solar_3d_model.py simulate --json > result.json

Use inside another Python app (for example a Streamlit platform):

  from solar_3d_model import build_html, simulate
  html = build_html(dict(site="jeddah", P=5, tes=6, bess=6))
  import streamlit.components.v1 as components
  components.html(html, height=820, scrolling=False)
  result = simulate(site="jeddah", P=5, tes=6, bess=6)

SharePoint
----------
`python solar_3d_model.py sharepoint` signs you in (a code is shown; open the address and type it),
then adds "Solar Choice.url" to the aPlatforms folder set in SHAREPOINT_FOLDER_URL. It shows up as a
link like your other items. `--what html` or `--what both` also uploads the page itself, but SharePoint
usually will not run scripts in an uploaded .html. If your organisation blocks the sign-in, pass your
own app id with --client-id, or an existing Graph token with --token / GRAPH_TOKEN.

Offline / corporate network
---------------------------
The 3D page loads Three.js r128 from public CDNs. If those are blocked, download
  https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js
  https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js
and run:  python solar_3d_model.py html --three three.min.js --orbit OrbitControls.js
Both files are then embedded and the page works without internet.

Notes
-----
* Site climates are rounded estimates. Replace them with measured data (TMY or
  on-site pyranometer) before using the numbers for a real decision.
* Costs, water use and lifecycle emissions are indicative literature values.
* The page is a browser app: open the .html file locally or host it on a web
  server. SharePoint document libraries usually download or block scripts in
  uploaded .html files instead of running them.
"""
import argparse
import base64
import json
import math
import os
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
import webbrowser
import http.server

# ---------------------------------------------------------------------------
# 1. PHYSICS ENGINE (Python port of the JavaScript model used in the 3D page)
# ---------------------------------------------------------------------------
S0 = 1361.0
D2R = math.pi / 180.0
MDAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
# Klein (1977) recommended average day of each month
MDOY = [17, 47, 75, 105, 135, 162, 198, 228, 258, 288, 318, 344]
MNAMES = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
_CUM = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334, 365]

# Atmosphere: Bird and Hulstrom (1981) broadband clear-sky model
O3_CM = 0.30          # ozone column, atm-cm
BA = 0.85             # aerosol forward-scattering ratio
DIFF_SCALE = 0.70     # scale on Bird's sky-diffuse term (fitted to measured diffuse fraction, see calibrate.py)
ANG_RATIO = 1.24      # aerosol optical depth at 380 nm over 500 nm (Angstrom exponent about 0.8)
# PV field
PV_GAMMA = 0.0032     # power temperature coefficient, 1/K
PV_DC_LOSS = 0.955    # wiring, mismatch, degradation allowance
INV_EFF = 0.985       # inverter
GCR_FIXED = 0.40      # ground-cover ratio, fixed tilt
GCR_TRACK = 0.35      # ground-cover ratio, single-axis tracker (backtracking)
ROT_MAX = 60.0 * D2R  # tracker rotation limit
N_SUB = 3             # bypass-diode substrings (portrait modules)
STOW_W = 18.0         # m/s, wind stow
# Parabolic trough field (EuroTrough-class)
CSP_OPT = 0.76        # peak optical efficiency (clean mirrors, normal incidence)
PB_GROSS = 0.38       # steam-cycle gross efficiency at design
PB_K_DRY = 0.0070     # relative efficiency loss per K above 25 C, air-cooled condenser
PB_K_WET = 0.0015     # same, wet cooling
PB_PARASITIC = 0.90   # pumps, trackers, cooling fans
# Collector types. 'lat' is the collector in the aes SolaReactor offer (aes booklet v4, Oct 2018):
# Gossamer Large Aperture Trough, 7.5 m aperture, 12 m modules, 2 x 16 modules = 384 m loop, 70 mm receiver.
# Its optical gain uses the booklet's own loop thermal efficiency, 78 % against 74 % for the RP3 trough at
# 750 W/m2 DNI (0.76 x 78/74 = 0.80); this is the vendor's figure, not an independent test.
# Focal length keeps the RP3 rim angle (about 80 deg); row pitch keeps the RP3 ground-cover ratio (0.385).
CSP_TECHS = {
    "lat": dict(name="Gossamer LAT (aes SolaReactor offer)", opt=0.80, w=7.5, f=2.22, pitch=19.5, loop=384.0),
    "rp3": dict(name="EuroTrough / RP3 (industry standard)", opt=0.76, w=5.77, f=1.71, pitch=15.0, loop=600.0),
}
# Thermal desalination (MED) used as the turbine's heat sink, as in the offer: the turbine exhausts at about
# 70 C instead of about 40 C, so the steam cycle gives less power (assumed 12 % less), and the rejected heat
# makes fresh water: 3.6e9 J per MWh / 2.33e6 J per kg x gain output ratio 9 / 1000 kg per m3 = 13.9 m3 per MWh.
MED_ETA = 0.88
MED_M3_PER_MWH = 13.9


def clamp(x, a, b):
    return min(b, max(a, x))


def month_of(doy):
    for m in range(12):
        if doy <= _CUM[m + 1]:
            return m
    return 11


def pressure_ratio(elev):
    """p/p0 from the ISA barometric formula."""
    return (1.0 - 2.25577e-5 * elev) ** 5.25588


def sun_pos(site, doy, h):
    """Solar position for a site at local standard clock hour h (Spencer 1971, longitude and time-zone corrected)."""
    b = 2 * math.pi * (doy - 1 + (h - site["tz"] - 12.0) / 24.0) / 365.0   # fractional day, UT-noon based
    eot = 229.18 * (0.000075 + 0.001868 * math.cos(b) - 0.032077 * math.sin(b)
                    - 0.014615 * math.cos(2 * b) - 0.040849 * math.sin(2 * b))   # minutes
    dec = (0.006918 - 0.399912 * math.cos(b) + 0.070257 * math.sin(b) - 0.006758 * math.cos(2 * b)
           + 0.000907 * math.sin(2 * b) - 0.002697 * math.cos(3 * b) + 0.00148 * math.sin(3 * b))
    e0 = (1.000110 + 0.034221 * math.cos(b) + 0.001280 * math.sin(b)
          + 0.000719 * math.cos(2 * b) + 0.000077 * math.sin(2 * b))
    sh = h + (site["lon"] - 15.0 * site["tz"]) / 15.0 + eot / 60.0    # apparent solar time
    ha = (sh - 12.0) * 15.0 * D2R
    ha = (ha + math.pi) % (2 * math.pi) - math.pi
    la = site["lat"] * D2R
    sin_el = math.sin(la) * math.sin(dec) + math.cos(la) * math.cos(dec) * math.cos(ha)
    el = math.asin(clamp(sin_el, -1, 1))
    cos_el = math.cos(el)
    g = 0.0
    if cos_el > 1e-3:
        g = math.acos(clamp((sin_el * math.sin(la) - math.sin(dec)) / (cos_el * math.cos(la)), -1, 1))
        if ha < 0:
            g = -g
    return dict(sinEl=sin_el, el=el, cosEl=cos_el, g=g, E0=e0, sh=sh, dec=dec, eot=eot,
                pr=pressure_ratio(site["elev"]), elev=site["elev"], pw=site["pw"][month_of(doy)], alb=site["alb"])


def irradiance(sp, c, aod):
    """Bird and Hulstrom (1981) clear sky, then cloud. aod = aerosol optical depth at 500 nm,
    c = fraction of time the sun disk is obscured."""
    if sp["sinEl"] < 0.03:
        return dict(ghi=0.0, dni=0.0, dhi=0.0)
    el_deg = sp["el"] / D2R
    mr = min(38.0, 1 / (sp["sinEl"] + 0.50572 * (6.07995 + el_deg) ** -1.6364))   # Kasten-Young 1989 relative air mass
    mp = mr * sp["pr"]                                                           # pressure-corrected
    i0 = S0 * sp["E0"]
    tr = math.exp(-0.0903 * mp ** 0.84 * (1 + mp - mp ** 1.01))                  # Rayleigh
    u3 = O3_CM * mr
    to = 1 - 0.1611 * u3 * (1 + 139.48 * u3) ** -0.3035 - 0.002715 * u3 / (1 + 0.044 * u3 + 0.0003 * u3 * u3)
    tum = math.exp(-0.0127 * mp ** 0.26)                                         # mixed gases
    aw = sp["pw"] * mr
    tw = 1 - 2.4959 * aw / ((1 + 79.034 * aw) ** 0.6828 + 6.385 * aw)            # water vapour
    ta_od = 0.2758 * ANG_RATIO * aod + 0.35 * aod
    ta = math.exp(-(ta_od ** 0.873) * (1 + ta_od - ta_od ** 0.7088) * mr ** 0.9108)   # aerosol
    dni_c = 0.9662 * i0 * tr * to * tum * tw * ta
    taa = 1 - 0.1 * (1 - mp + mp ** 1.06) * (1 - ta)
    tas = ta / taa
    ias = DIFF_SCALE * (i0 * sp["sinEl"] * 0.79 * to * tum * tw * taa * (0.5 * (1 - tr) + BA * (1 - tas))
                        / (1 - mp + mp ** 1.02))
    rs = 0.0685 + (1 - BA) * (1 - tas)
    ghi_c = (dni_c * sp["sinEl"] + ias) / (1 - sp["alb"] * rs)
    dhi_c = max(0.0, ghi_c - dni_c * sp["sinEl"])
    # c = fraction of time the sun disk is obscured. Obscured time still passes kappa of clear GHI:
    # 0.24 under full overcast, rising to about 0.5 under broken or thin cloud (cloud enhancement, cirrus).
    kappa = 0.15 + 0.9 * (1 - c)
    dni = dni_c * (1 - c)
    ghi = ghi_c * ((1 - c) + c * kappa)
    dhi = max(0.05 * ghi, ghi - dni * sp["sinEl"])
    ghi = dni * sp["sinEl"] + dhi
    return dict(ghi=ghi, dni=dni, dhi=dhi)


# ------------------------------------------------------------------ PV
def pv_orient(pl, sp, w):
    """Panel tilt (rad), cosine of incidence and row-shaded fraction of the module."""
    sin_el, cos_el, g = sp["sinEl"], sp["cosEl"], sp["g"]
    if pl["track"]:
        if w >= STOW_W or sin_el <= 0.0:
            return 0.0, max(0.0, sin_el), 0.0                       # flat stow in high wind and at night
        phi_i = math.atan2(cos_el * math.sin(g), sin_el)               # sun angle from vertical in the E-W plane
        bt = math.acos(min(1.0, math.cos(phi_i) / GCR_TRACK))          # backtracking offset
        phi = phi_i - math.copysign(bt, phi_i) if phi_i != 0 else 0.0
        phi = clamp(phi, -ROT_MAX, ROT_MAX)
        cos_ideal = math.sqrt(max(0.0, 1 - cos_el ** 2 * math.cos(g) ** 2))
        return abs(phi), max(0.0, cos_ideal * math.cos(phi_i - phi)), 0.0
    b = pl["tilt"] * D2R
    cos_t = max(0.0, sin_el * math.cos(b) + cos_el * math.sin(b) * math.cos(g))
    fs = 0.0
    if cos_t > 0 and cos_el > 1e-3 and math.cos(g) > 1e-3:
        ap = math.atan(sin_el / cos_el / math.cos(g))                    # profile angle in the N-S plane
        fs = max(0.0, 1 - (1 / GCR_FIXED) * math.sin(ap) / math.sin(ap + b))
    return b, cos_t, fs


def pv_step(pl, soil, sp, ir, ta, w):
    b, cos_t, fs = pv_orient(pl, sp, w)
    iam = clamp(1 - 0.05 * (1 / max(cos_t, 0.05) - 1), 0, 1)
    i0n = S0 * sp["E0"]
    ai = clamp(ir["dni"] / i0n, 0.0, 0.95)                               # Hay-Davies anisotropy index
    rb = cos_t / max(sp["sinEl"], 0.087)
    d_poa = ir["dhi"] * (ai * rb + (1 - ai) * (1 + math.cos(b)) / 2)
    r_poa = ir["ghi"] * pl.get("alb", 0.2) * (1 - math.cos(b)) / 2
    g = max(0.0, ir["dni"] * cos_t * iam + 0.97 * d_poa + 0.95 * r_poa)
    f_el = math.ceil(fs * N_SUB - 1e-9) / N_SUB if fs > 0 else 0.0       # bypass-diode stepwise shading loss
    g_eff = g * (1 - f_el)
    tc = ta + g / 800 * 25 * 9.5 / (5.7 + 3.8 * w)
    eta = 1 - PV_GAMMA * (tc - 25)
    low = 1 - 0.06 * max(0.0, 1 - g_eff / 250)
    pdc = pl["P"] * pl["dcac"] * (g_eff / 1000) * eta * low * (1 - soil) * PV_DC_LOSS
    ac = pdc * INV_EFF
    return dict(pac=min(ac, pl["P"]), poa=g, Tc=tc if g > 20 else ta, clip=max(0.0, ac - pl["P"]), shade=f_el, beta=b)


# ------------------------------------------------------------------ CSP
def eta_net(ta, x, cool):
    k = PB_K_DRY if cool == "dry" else PB_K_WET
    e = clamp(PB_GROSS * (1 - k * (ta - 25)), 0.2, 0.42) * (MED_ETA if cool == "med" else 1.0)
    return e * (1 - 0.28 * (1 - clamp(x, 0, 1)) ** 1.6) * PB_PARASITIC


def csp_step(pl, soil, sp, ir, ta, w):
    cos_t = math.sqrt(max(0.0, 1 - sp["cosEl"] ** 2 * math.cos(sp["g"]) ** 2))
    th = math.acos(clamp(cos_t, 0, 1))
    ct = max(cos_t, 0.05)
    iam = clamp(1 + 0.0327 * th / ct - 0.1351 * th * th / ct, 0.0, 1.0)  # trough incidence-angle modifier
    end = max(0.0, 1 - pl["f"] * math.tan(min(th, 1.5)) / pl["loop"])   # receiver end loss
    phi_i = math.atan2(sp["cosEl"] * math.sin(sp["g"]), sp["sinEl"])
    fu = clamp(pl["pitch"] * math.cos(phi_i) / pl["w"], 0.0, 1.0)       # row-to-row shading
    w_f = 1.0 if w <= 10 else 0.0 if w >= 18 else 1 - (w - 10) / 8
    d_eff = ir["dni"] * cos_t
    qabs = d_eff * pl["opt"] * iam * end * fu * (1 - soil) * w_f
    qloss = 55 * (max(0.0, 390 - ta) / 365) ** 1.15 * (1 + 0.015 * w)
    start = clamp((d_eff - 200) / 100, 0, 1)
    qnet = max(0.0, qabs - qloss) * start
    return dict(Qf=pl["A"] * qnet / 1e6, qnet=qnet, dEff=d_eff, stow=w >= 18, iam=iam, fu=fu)


# ------------------------------------------------------------------ plant, day and year
PROFILES = {
    "office": lambda h: 1.0 if 7 <= h < 17 else 0.15,
    "shift": lambda h: 0.9 if 6 <= h < 22 else 0.4,
    "process": lambda h: 1.0 if 8 <= h < 18 else 0.85,
}


def load_at(L, h):
    return L["P"] if L["mode"] == "full" else L["peak"] * PROFILES[L["prof"]](int(math.floor(h)))


def make_plants(P, tes=0, bess=0, mount="fixed", cool="dry", ctech="lat"):
    T = CSP_TECHS[ctech]
    qd = P / (PB_GROSS * (MED_ETA if cool == "med" else 1.0) * 0.9)
    sm = 1.15 + 0.13 * tes
    return dict(
        pv=dict(P=P, dcac=min(2.6, 1.25 + 0.2 * bess), track=(mount == "track"), tilt=0.0, bessH=bess),
        csp=dict(P=P, Qd=qd, SM=sm, A=sm * qd * 1e6 / (476 * T["opt"] / CSP_OPT), cool=cool, tesH=tes, ctech=ctech,
                 opt=T["opt"], w=T["w"], f=T["f"], pitch=T["pitch"], loop=T["loop"]),
    )


def soil_state(tech, site, doy, wx, clean):
    """Average soiling loss on a representative day: cleaning interval shortened by monthly rain."""
    m = month_of(doy)
    days = 0 if wx.get("rain") else clean / 2 / (1 + site["rain"][m] / 20.0)
    if tech == "pv":
        return min(0.45, 0.003 * site["dust"] * days)
    return min(0.7, 0.006 * site["dust"] * days)


def day_run(tech, pl, site, doy, wx, L, clean, dt=0.25):
    """One 24 h run. Returns hourly arrays and energy totals (MWh)."""
    n = int(round(24 / dt))
    m = month_of(doy)
    soil = soil_state(tech, site, doy, wx, clean)
    sw = wx.get("sw", site["sw"][m])
    P = pl["P"]
    ecap = pl["bessH"] * P if tech == "pv" else pl["tesH"] * pl["Qd"]
    plx = dict(pl, tilt=site["tilt"], alb=site["alb"]) if tech == "pv" else pl
    soc = 0.0
    r = None
    for _ in range(3):  # three passes so storage reaches a daily steady state
        r = dict(t=[], ghi=[], dni=[], dhi=[], Ta=[], pot=[], delivered=[], load=[], soc=[], poa=[], clip=[], el=[],
                 Edel=0.0, Eld=0.0, Epot=0.0, Eun=0.0, EdN=0.0, ElN=0.0, Ppk=0.0, hrs=0.0,
                 Hghi=0.0, Hdni=0.0, Hpoa=0.0, maxTc=0.0, soil=soil, Esh=0.0)
        for i in range(n):
            h = i * dt
            sp = sun_pos(site, doy, h)
            ir = irradiance(sp, wx["c"], wx["aod"])
            ta = wx["T"] + sw * math.cos(2 * math.pi * (sp["sh"] - 15) / 24)
            lh = load_at(L, h)
            poa = 0.0
            clipv = 0.0
            if tech == "pv":
                s = pv_step(plx, soil, sp, ir, ta, wx["w"])
                pot = s["pac"]
                poa = s["poa"]
                clipv = s["clip"]
                r["maxTc"] = max(r["maxTc"], s["Tc"])
                pu = s["pac"] + s["clip"]
                d = min(pu, lh, P)
                sur, deficit = pu - d, lh - d
                eta = math.sqrt(0.88)
                chg = min(sur, max(0.0, (ecap - soc) / (dt * eta)), P)
                soc += chg * eta * dt
                sur -= chg
                dis = min(deficit, soc * eta / dt, P - d)
                soc -= dis / eta * dt
                delivered, unused = d + dis, sur
            else:
                s = csp_step(pl, soil, sp, ir, ta, wx["w"])
                qd = pl["Qd"]
                eta_f = eta_net(ta, 1, pl["cool"])
                p_cap = qd * eta_f
                pot = min(p_cap, s["Qf"] * eta_net(ta, min(1, s["Qf"] / qd), pl["cool"]))
                want = min(lh, p_cap)
                qw = want / eta_f
                for _k in range(3):
                    qw = want / eta_net(ta, min(1, qw / qd), pl["cool"])
                qw = min(qw, qd)
                qt = max(qw, 0.2 * qd)
                from_f = min(s["Qf"], qt)
                dis = min(qt - from_f, soc / dt)
                if from_f + dis < 0.2 * qd - 1e-9:
                    from_f, dis = 0.0, 0.0
                q_run = from_f + dis
                pe = q_run * eta_net(ta, q_run / qd, pl["cool"])
                delivered = min(lh, pe)
                unused = pe - delivered
                left = s["Qf"] - from_f
                room = max(0.0, (ecap - soc) / dt / 0.97)
                chg = min(left, room)
                soc = max(0.0, soc + (chg * 0.97 - dis) * dt)
                unused += (left - chg) * eta_f
            r["t"].append(h); r["ghi"].append(ir["ghi"]); r["dni"].append(ir["dni"]); r["dhi"].append(ir["dhi"])
            r["Ta"].append(ta); r["pot"].append(pot); r["delivered"].append(delivered); r["load"].append(lh)
            r["soc"].append(soc); r["poa"].append(poa); r["clip"].append(clipv); r["el"].append(sp["el"] / D2R)
            r["Edel"] += delivered * dt; r["Eld"] += lh * dt; r["Epot"] += pot * dt; r["Eun"] += unused * dt
            r["Ppk"] = max(r["Ppk"], delivered)
            if delivered > 0.02 * P:
                r["hrs"] += dt
            if h >= 18 or h < 6:
                r["EdN"] += delivered * dt; r["ElN"] += lh * dt
            r["Hghi"] += ir["ghi"] * dt / 1000; r["Hdni"] += ir["dni"] * dt / 1000; r["Hpoa"] += poa * dt / 1000
    r["Ecap"] = ecap
    return r


def year_run(tech, pl, site, L, clean):
    o = dict(tech=tech, months=[], Edel=0.0, Eld=0.0, EdN=0.0, ElN=0.0, Efull=0.0, Hghi=0.0, Hdni=0.0, Hpoa=0.0)
    for m in range(12):
        wx = dict(c=site["cl"][m], aod=site["aod"][m], T=site["T"][m], w=site["w"], rain=False)
        co = day_run(tech, pl, site, MDOY[m], wx, dict(L, mode="co"), clean)
        fu = day_run(tech, pl, site, MDOY[m], wx, dict(L, mode="full"), clean)
        d = MDAYS[m]
        o["months"].append(dict(delivered=co["Edel"] * d, full=fu["Edel"] * d, ghi=co["Hghi"], dni=co["Hdni"]))
        o["Edel"] += co["Edel"] * d; o["Eld"] += co["Eld"] * d
        o["EdN"] += co["EdN"] * d; o["ElN"] += co["ElN"] * d
        o["Efull"] += fu["Edel"] * d
        o["Hghi"] += co["Hghi"] * d; o["Hdni"] += co["Hdni"] * d; o["Hpoa"] += co["Hpoa"] * d
    return o


# ------------------------------------------------------------------ resource helpers (used by calibration and tests)
def daily_irradiation(site, doy, c, aod, dt=0.25):
    """Daily GHI and DNI sums (kWh/m2/day) for one representative day."""
    hg = hd = 0.0
    for i in range(int(round(24 / dt))):
        sp = sun_pos(site, doy, i * dt)
        ir = irradiance(sp, c, aod)
        hg += ir["ghi"] * dt / 1000
        hd += ir["dni"] * dt / 1000
    return hg, hd


def annual_mean_daily(site, cl=None, aod=None):
    """Annual mean daily GHI and DNI (kWh/m2/day), weighted by month length."""
    cl = site["cl"] if cl is None else cl
    aod = site["aod"] if aod is None else aod
    g = d = 0.0
    for m in range(12):
        a, b = daily_irradiation(site, MDOY[m], cl[m], aod[m])
        g += a * MDAYS[m]
        d += b * MDAYS[m]
    return g / 365.0, d / 365.0


def best_tilt(site, grid=range(0, 46)):
    """Fixed tilt (deg, facing the equator) that maximises annual plane-of-array energy at this site."""
    best, bt = -1.0, 0
    pl = dict(P=1.0, dcac=1.0, track=False, alb=site["alb"])
    for tilt in grid:
        pl["tilt"] = tilt
        e = 0.0
        for m in range(12):
            wx = dict(c=site["cl"][m], aod=site["aod"][m])
            for i in range(0, 96, 1):
                sp = sun_pos(site, MDOY[m], i * 0.25)
                ir = irradiance(sp, wx["c"], wx["aod"])
                if ir["ghi"] <= 0:
                    continue
                s = pv_step(pl, 0.0, sp, ir, 25.0, 3.0)
                e += s["pac"] * MDAYS[m] * 0.25
        if e > best:
            best, bt = e, tilt
    return bt


