# Stress scenarios used by the weather-resilience score
SCENARIOS = [
    ("clear", lambda t: dict(c=0, aod=0.12, T=t["T"], w=3, rain=False)),
    ("haze", lambda t: dict(c=0.1, aod=0.6, T=t["T"], w=3, rain=False)),
    ("broken", lambda t: dict(c=0.5, aod=0.2, T=t["T"], w=4, rain=False)),
    ("overcast", lambda t: dict(c=0.9, aod=0.2, T=t["T"], w=4, rain=False)),
    ("dust", lambda t: dict(c=0.1, aod=2.2, T=t["T"], w=14, rain=False)),
    ("heat", lambda t: dict(c=0, aod=0.15, T=t["T"] + 10, w=2, rain=False)),
    ("gale", lambda t: dict(c=0, aod=0.12, T=t["T"], w=20, rain=False)),
    ("rain", lambda t: dict(c=0.85, aod=0.1, T=t["T"] - 4, w=5, rain=True)),
    ("cold", lambda t: dict(c=0, aod=0.1, T=t["T"] - 12, w=2, rain=False)),
]
CRITERIA = [("cov", "Energy covering your load"), ("cost", "Cost vs Saudi tariff"), ("env", "Environment"),
            ("wx", "Weather resilience"), ("night", "Evening and night supply"),
            ("grid", "Fit to LV / MV connection"), ("om", "Operation effort")]


# Saudi electricity tariff effective 1 January 2027 (halalas per kWh, before VAT).
# Commercial 25 up to 6,000 kWh/month then 35; industrial 23 flat; government 35 flat.
# Source: Saudi Energy schedule as reported by MEED, Saudi Gazette and others, October 2026.
# The fixed monthly fee depends on breaker size, not on solar, so it is left out of the savings.
SAR_PER_USD = 3.75
TARIFF = {"commercial": (25, 35, 6000), "industrial": (23, 23, 1e12), "government": (35, 35, 1e12)}


def bill_year(kwh_year, tar):
    a, b, cap = TARIFF[tar]
    m = kwh_year / 12
    return 12 * (min(m, cap) * a + max(0.0, m - cap) * b) / 100


def metrics(tech, Y, pl, P, bess, tes, cool, grid_factor=0.65, tar="industrial", crf=0.0858):
    ef = Y["Efull"]          # crf: capital recovery factor, 0.0858 = 7 % over 25 years
    desal = 0.0              # fresh water from MED, m3 per day (CSP with cool='med' only)
    if tech == "pv":
        kwdc = P * 1000 * pl["dcac"]
        unit = 780 if pl["track"] else 700
        sc = (20 / P) ** 0.1 if P < 20 else 1
        c1 = kwdc * unit * sc
        c2 = bess * P * 1000 * 250 * ((20 / P) ** 0.08 if P < 20 else 1)
        cap = c1 + c2
        ann = c1 * (crf + 0.018) + c2 * (0.1098 + 0.02)
        om = c1 * 0.018 + c2 * 0.02
        land = kwdc / 1000 * (2.4 if pl["track"] else 1.9)
        water = ef * 100 / 1e6
        cf = ef / (P * 8760)
        ghg = 48 * clamp(0.22 / max(cf, 0.05), 0.6, 1.8) + (bess * P * 75 / 15 / ef * 1000 if ef > 0 else 0)
    else:
        sc = (50 / P) ** 0.2 if P < 50 else 1
        cap = ((1200 + 300) * P * 1000 + 250 * pl["A"] + 25 * tes * pl["Qd"] * 1000) * sc
        ann = cap * (crf + 0.025)
        om = cap * 0.025
        land = pl["A"] / 0.26 / 1e4
        water = ef * (3000 if cool == "wet" else 300) / 1e6
        cf = ef / (P * 8760)
        ghg = 27 * clamp(0.30 / max(cf, 0.05), 0.6, 1.8)
        if cool == "med":
            eg = PB_GROSS * MED_ETA
            desal = ef / PB_PARASITIC * (1 - eg) / eg * MED_M3_PER_MWH / 365
    lcoe = ann / ef if ef > 1 else float("nan")
    life = ghg * ef / 1000
    kl, kd = Y["Eld"] * 1000, Y["Edel"] * 1000
    sav = bill_year(kl, tar) - bill_year(max(0.0, kl - kd), tar)
    ann_s, cap_s, om_s = ann * SAR_PER_USD, cap * SAR_PER_USD, om * SAR_PER_USD
    return dict(
        energy_gwh=Y["Edel"] / 1000,
        coverage=Y["Edel"] / Y["Eld"] if Y["Eld"] > 0 else 0.0,
        night_coverage=Y["EdN"] / Y["ElN"] if Y["ElN"] > 0 else 0.0,
        capacity_factor=ef / (P * 8760), lcoe_usd_mwh=lcoe, land_ha=land, water_ML_yr=water, desal_m3_day=desal,
        lifecycle_g_kwh=ghg, lifecycle_t_yr=life, avoided_t_yr=grid_factor * ef - life,
        capex_sar=cap_s, bill_saving_sar_yr=sav, net_gain_sar_yr=sav - ann_s,
        payback_yr=cap_s / (sav - om_s) if sav - om_s > 0 else float("inf"),
        cost_hal_kwh=ann_s / kd * 100 if kd > 0 else float("nan"),
        grid_hal_kwh=sav / kd * 100 if kd > 0 else float(TARIFF[tar][1]),
    )


def grid_fit(P):
    return 1.5 if P < 2 else 3 if P < 5 else 4.5 if P < 20 else 6.5 if P < 50 else 8


def simulate(site="jeddah", P=5.0, peak=None, prof="process", mount="fixed", cool="dry", ctech="lat",
             bess=0, tes=0, clean=14, month=6, grid_factor=0.65,
             weights=None, tar="industrial"):
    """Full run: yearly energy, costs, environment, weather stress test and the weighted decision."""
    weights = weights or dict(cov=20, cost=20, env=15, wx=15, night=10, grid=10, om=10)
    s = SITES[site]
    peak = P if peak is None else peak
    pls = make_plants(P, tes, bess, mount, cool, ctech)
    L = dict(P=P, peak=peak, prof=prof)
    Y = {k: year_run(k, pls[k], s, L, clean) for k in ("pv", "csp")}
    t = dict(T=s["T"][month])
    stress = []
    for name, f in SCENARIOS:
        wx = f(t)
        stress.append((name, {k: day_run(k, pls[k], s, MDOY[month], wx, dict(L, mode="full"), clean)["Edel"] for k in ("pv", "csp")}))
    base = stress[0][1]
    ret = {k: sum((e[k] / base[k] if base[k] > 0 else 0.0) for _, e in stress[1:]) / (len(stress) - 1) for k in ("pv", "csp")}
    M = {k: metrics(k, Y[k], pls[k], P, bess, tes, cool, grid_factor, tar) for k in ("pv", "csp")}

    def hi(a, b):
        mx = max(a, b)
        return (10 * a / mx, 10 * b / mx) if mx > 0 else (0.0, 0.0)

    def lo(a, b):
        a = 1e9 if not math.isfinite(a) else a
        b = 1e9 if not math.isfinite(b) else b
        if a <= 0 and b <= 0:
            return (10.0, 10.0)
        mn = min(a, b)
        return (10 * mn / a, 10 * mn / b)

    S = {"cov": hi(M["pv"]["coverage"], M["csp"]["coverage"]),
         "night": hi(M["pv"]["night_coverage"], M["csp"]["night_coverage"]),
         "cost": (hi(max(0.0, M["pv"]["net_gain_sar_yr"]), max(0.0, M["csp"]["net_gain_sar_yr"]))
                  if max(M["pv"]["net_gain_sar_yr"], M["csp"]["net_gain_sar_yr"]) > 0
                  else lo(M["pv"]["cost_hal_kwh"], M["csp"]["cost_hal_kwh"])),
         "wx": hi(ret["pv"], ret["csp"])}
    ln, wt, gh = (lo(M["pv"]["land_ha"], M["csp"]["land_ha"]), lo(M["pv"]["water_ML_yr"], M["csp"]["water_ML_yr"]),
                  lo(M["pv"]["lifecycle_g_kwh"], M["csp"]["lifecycle_g_kwh"]))
    S["env"] = tuple((ln[i] + wt[i] + gh[i]) / 3 for i in (0, 1))
    S["grid"] = (9.0, grid_fit(P))
    S["om"] = (9.0, 4.0)
    sw = sum(weights.values()) or 1
    total = {k: sum(weights[c] * S[c][i] for c, _ in CRITERIA) / sw for i, k in enumerate(("pv", "csp"))}
    return dict(site=s["name"], tariff=tar, plants=pls, year=Y, metrics=M, weather_retention=ret,
                stress={n: e for n, e in stress}, scores=S, total=total,
                winner="pv" if total["pv"] >= total["csp"] else "csp")


