THREE_TAG = '<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>'
ORBIT_TAG = '<script src="https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js"></script>'
INIT_KEYS = {"site", "month", "P", "peak", "prof", "mount", "cool", "ctech", "bess", "tes", "clean", "welcome", "tour", "tar", "adv"}


def build_html(init=None, three_src=None, orbit_src=None):
    """Return the complete, self-contained HTML page as a string.

    init       dict of starting values: site, month (0-11), P (MW), peak (MW), prof
               ('office'|'shift'|'process'), mount ('fixed'|'track'), cool ('dry'|'wet'),
               bess (battery hours 0-8), tes (thermal storage hours 0-12), clean (wash days),
               adv (True opens the full control panels instead of the simple view),
               tar ('commercial'|'industrial'|'government'), welcome (True shows a start screen),
               tour (True opens Explain mode and starts the guided tour at once).
    three_src  optional text of three.min.js to embed instead of loading it from a CDN.
    orbit_src  optional text of OrbitControls.js to embed.
    """
    init = dict(init or {})
    bad = set(init) - INIT_KEYS
    if bad:
        raise ValueError("unknown setting(s): %s" % ", ".join(sorted(bad)))
    if "site" in init and init["site"] not in SITES:
        raise ValueError("site must be one of: %s" % ", ".join(SITES))
    js = JS.replace("/*__INIT__*/", "Object.assign(st,%s);" % json.dumps(init))
    body = BODY
    scripts = (THREE_TAG if three_src is None else "<script>%s</script>" % three_src) + "\n" + \
              (ORBIT_TAG if orbit_src is None else "<script>%s</script>" % orbit_src)
    return ("<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\">"
            "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">"
            + HEAD + "<style>html,body{margin:0}</style></head><body>\n"
            + body + "\n" + scripts + "\n<script>\n" + js + "\n</script>\n</body></html>\n")


