def _http(method, url, headers=None, data=None):
    req = urllib.request.Request(url, data=data, method=method, headers=headers or {})
    try:
        with urllib.request.urlopen(req, timeout=60) as r:
            return r.status, r.read()
    except urllib.error.HTTPError as e:
        return e.code, e.read()


def sp_token(client_id=GRAPH_CLIENT_ID, tenant="organizations"):
    """Sign in with a device code: open the printed address, type the code, approve."""
    base = "https://login.microsoftonline.com/%s/oauth2/v2.0" % tenant
    form = {"Content-Type": "application/x-www-form-urlencoded"}
    st, b = _http("POST", base + "/devicecode", form, urllib.parse.urlencode(
        {"client_id": client_id, "scope": "https://graph.microsoft.com/Files.ReadWrite.All"}).encode())
    d = json.loads(b)
    if st != 200 or "device_code" not in d:
        raise RuntimeError("Sign-in could not start: %s" % d.get("error_description", b[:200]))
    print(d["message"])
    end = time.time() + int(d.get("expires_in", 900))
    while time.time() < end:
        time.sleep(int(d.get("interval", 5)))
        st, b = _http("POST", base + "/token", form, urllib.parse.urlencode(
            {"grant_type": "urn:ietf:params:oauth:grant-type:device_code", "client_id": client_id,
             "device_code": d["device_code"]}).encode())
        t = json.loads(b)
        if "access_token" in t:
            return t["access_token"]
        if t.get("error") not in ("authorization_pending", "slow_down"):
            raise RuntimeError("Sign-in refused: %s" % t.get("error_description", t.get("error")))
    raise RuntimeError("Sign-in timed out")


def sp_share_id(url):
    return "u!" + base64.urlsafe_b64encode(url.encode()).decode().rstrip("=")


def sharepoint_upload(files, folder_url=SHAREPOINT_FOLDER_URL, token=None, client_id=GRAPH_CLIENT_ID, tenant="organizations"):
    """Upload {file name: bytes} into the SharePoint folder behind a sharing link. Returns the new items' web addresses."""
    token = token or sp_token(client_id, tenant)
    h = {"Authorization": "Bearer " + token}
    st, b = _http("GET", GRAPH + "/shares/%s/driveItem?$select=id,name,folder,parentReference" % sp_share_id(folder_url), h)
    if st != 200:
        raise RuntimeError("Could not open the folder (HTTP %d): %s" % (st, b[:300]))
    item = json.loads(b)
    if "folder" not in item:
        raise RuntimeError("That sharing link is not a folder.")
    drive = item["parentReference"]["driveId"]
    out = []
    for name, data in files.items():
        url = "%s/drives/%s/items/%s:/%s:/content?@microsoft.graph.conflictBehavior=replace" % (
            GRAPH, drive, item["id"], urllib.parse.quote(name))
        st, b = _http("PUT", url, dict(h, **{"Content-Type": "application/octet-stream"}), data)
        if st not in (200, 201):
            raise RuntimeError("Upload of %s failed (HTTP %d): %s" % (name, st, b[:300]))
        out.append(json.loads(b).get("webUrl", name))
    return out


def internet_shortcut(url):
    """A .url file: SharePoint shows it as a link, like the other items in aPlatforms."""
    return ("[InternetShortcut]\r\nURL=%s\r\n" % url).encode("utf-8")


