def _common(p):
    p.add_argument("--site", default="jeddah", choices=sorted(SITES), help="climate site")
    p.add_argument("--month", type=int, default=7, choices=range(1, 13), metavar="1-12", help="month shown in the day view")
    p.add_argument("--plant-mw", type=float, default=5.0, help="plant rating, MW AC")
    p.add_argument("--load-mw", type=float, default=None, help="company peak load, MW (default: same as plant)")
    p.add_argument("--load-pattern", default="process", choices=sorted(PROFILES), help="daily load shape")
    p.add_argument("--pv-mount", default="fixed", choices=["fixed", "track"])
    p.add_argument("--csp-cooling", default="med", choices=["dry", "wet", "med"],
                   help="dry or wet condenser, or med: thermal desalination as the heat sink (aes offer)")
    p.add_argument("--csp-tech", default="lat", choices=sorted(CSP_TECHS),
                   help="lat: Gossamer Large Aperture Trough (aes offer); rp3: industry-standard trough")
    p.add_argument("--offer", action="store_true", help="aes SolaReactor set-up: LAT collector, MED desalination, 14 h salt storage")
    p.add_argument("--battery-h", type=int, default=0, help="PV battery hours, 0-8")
    p.add_argument("--storage-h", type=int, default=14, help="CSP thermal storage hours, 0-16 (offer: 14)")
    p.add_argument("--wash-days", type=int, default=14, help="days between washing panels and mirrors")
    p.add_argument("--tariff", default="industrial", choices=sorted(TARIFF), help="Saudi tariff class from 1 Jan 2027")
    p.add_argument("--advanced", action="store_true", help="open the full control panels instead of the simple view")
    p.add_argument("--welcome", action="store_true", help="show a start screen (off by default for a clean view)")
    p.add_argument("--tour", action="store_true", help="start the guided tour immediately")


def _offer(a):
    if getattr(a, "offer", False):
        a.csp_tech, a.csp_cooling, a.storage_h = "lat", "med", 14
    return a


def _init_from(a):
    _offer(a)
    return dict(ctech=a.csp_tech, site=a.site, month=a.month - 1, P=a.plant_mw, peak=a.load_mw if a.load_mw is not None else a.plant_mw,
                prof=a.load_pattern, mount=a.pv_mount, cool=a.csp_cooling, bess=a.battery_h, tes=a.storage_h, clean=a.wash_days,
                welcome=a.welcome, tour=a.tour, tar=a.tariff, adv=a.advanced)


def _read(path):
    with open(path, "r", encoding="utf-8") as f:
        return f.read()


THREE_URL = "https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"
ORBIT_URL = "https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js"


def fetch_libs():
    """Download Three.js once (needs internet on this computer) so the page can carry it inside itself."""
    out = []
    for url in (THREE_URL, ORBIT_URL):
        cache = os.path.join(os.path.expanduser("~"), ".solar_choice_" + url.rsplit("/", 1)[1])
        if os.path.exists(cache) and os.path.getsize(cache) > 10000:
            out.append(_read(cache))
            continue
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(req, timeout=60) as r:
                text = r.read().decode("utf-8")
        except Exception as e:
            sys.exit("Could not download %s (%s).\nSave the two files yourself and use --three and --orbit:\n  %s\n  %s" % (url, e, THREE_URL, ORBIT_URL))
        with open(cache, "w", encoding="utf-8") as f:
            f.write(text)
        out.append(text)
    return out[0], out[1]


def cmd_html(a):
    three = _read(a.three) if a.three else None
    orbit = _read(a.orbit) if a.orbit else None
    if a.embed and not (three and orbit):
        three, orbit = fetch_libs()
    html = build_html(_init_from(a), three, orbit)
    with open(a.out, "w", encoding="utf-8") as f:
        f.write(html)
    path = os.path.abspath(a.out)
    print("Wrote", path)
    if not a.no_open:
        webbrowser.open("file://" + path)


def cmd_serve(a):
    """Run the page on a small local web server: http://localhost:PORT"""
    three = _read(a.three) if a.three else None
    orbit = _read(a.orbit) if a.orbit else None
    page = build_html(_init_from(a), three, orbit).encode("utf-8")

    class Handler(http.server.BaseHTTPRequestHandler):
        def do_GET(self):
            if self.path.split("?")[0] in ("/", "/index.html", "/solar_3d_model.html"):
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Length", str(len(page)))
                self.send_header("Cache-Control", "no-store")
                self.end_headers()
                self.wfile.write(page)
            else:
                self.send_error(404)

        def log_message(self, *args):
            pass

    try:
        srv = http.server.ThreadingHTTPServer((a.host, a.port), Handler)
    except OSError as e:
        sys.exit("Cannot start on %s:%d (%s). Try another port, for example --port 8080." % (a.host, a.port, e))
    shown = "localhost" if a.host in ("127.0.0.1", "localhost", "0.0.0.0") else a.host
    url = "http://%s:%d" % (shown, a.port)
    print("Solar Choice is running at", url, " (press Ctrl+C to stop)")
    if a.host == "0.0.0.0":
        print("Other computers on your network can open it with this computer's address and port", a.port)
    if not a.no_open:
        webbrowser.open(url)
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        print("\nStopped.")
    finally:
        srv.server_close()


def cmd_sharepoint(a):
    files = {}
    if a.what in ("link", "both"):
        files["Solar Choice.url"] = internet_shortcut(a.link)
    if a.what in ("html", "both"):
        three, orbit = fetch_libs()
        files["Solar Choice.html"] = build_html(_init_from(a), three, orbit).encode("utf-8")
    print("Folder:", a.folder_url)
    print("Will upload:", ", ".join(files))
    if a.dry_run:
        print("Dry run: nothing uploaded.")
        return
    token = a.token or os.environ.get("GRAPH_TOKEN")
    try:
        for u in sharepoint_upload(files, a.folder_url, token, a.client_id, a.tenant):
            print("Added:", u)
    except RuntimeError as e:
        sys.exit("SharePoint upload stopped: %s" % e)


