def cmd_simulate(a):
    _offer(a)
    r = simulate(site=a.site, P=a.plant_mw, peak=a.load_mw, prof=a.load_pattern, mount=a.pv_mount, cool=a.csp_cooling, ctech=a.csp_tech,
                 bess=a.battery_h, tes=a.storage_h, clean=a.wash_days, month=a.month - 1, tar=a.tariff)
